def transform(grid):
    """Recolor every solid single-color row or column to 2."""
    h, w = len(grid), len(grid[0])
    solid_rows = {r for r in range(h) if all(v == grid[r][0] for v in grid[r])}
    solid_cols = {c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))}
    return [[2 if r in solid_rows or c in solid_cols else grid[r][c]
             for c in range(w)] for r in range(h)]
